import { useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { AutomationService } from '../api/automations';
import { toRows } from './rows';

export function RunList({ automationId }: { automationId: string }) {
  const queryClient = useQueryClient();
  const [rows, setRows] = useState<unknown[]>([]);
  const [total, setTotal] = useState(0);
  useEffect(() => {
    let cancelled = false;
    AutomationService.listRuns(automationId, { limit: 10 }).then((response) => {
      const next = toRows(response.runs);
      if (!cancelled) {
        setRows(next);
        setTotal(response.total);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [automationId]);
  return <table data-client={String(!!queryClient)}>{rows.length}/{total}</table>;
}

