export function SlugField({ id, slug }: { id: string; slug: string }) {
  useQuery({ queryKey: ['x'], queryFn: () => 1 });
  const [state, setState] = useState('idle');
  useEffect(() => {
    const timer = setTimeout(async () => {
      const ok = await client.resume.saveSlug({ id, slug });
