import { useEffect, useState } from 'react';
import useSWR from 'swr';

export function Hasher({ bytes }: { bytes: Uint8Array }) {
  const { data } = useSWR('/me');
  const [hash, setHash] = useState('');
  const [clip, setClip] = useState('');
  const [fontReady, setFontReady] = useState(false);
  useEffect(() => {
    crypto.subtle.digest('SHA-256', bytes).then((buf) => setHash(String(buf.byteLength)));
    (async () => {
      setClip(await navigator.clipboard.readText());
    })();
    document.fonts.load('12px Inter').then(() => setFontReady(true));
  }, [bytes]);
  return <p>{data?.name}{hash}{clip}{String(fontReady)}</p>;
}

