import { useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { sleep } from '../lib/time';

export function SavedBanner({ savedAt }: { savedAt: number }) {
  useQuery({ queryKey: ['me'], queryFn: () => 1 });
  const [visible, setVisible] = useState(true);
  const [faded, setFaded] = useState(false);
  useEffect(() => {
    let alive = true;
    (async () => {
      await sleep(2500);
      if (alive) setVisible(false);
    })();
    delay(300).then(() => setFaded(true));
    return () => {
      alive = false;
    };
  }, [savedAt]);
  return visible ? <p data-faded={faded}>Saved</p> : null;
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));

import { useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { prewarmMonth, warmCategories } from './spreadsheet';

export function BudgetScreen({ month }: { month: string }) {
  useQuery({ queryKey: ['budgets'], queryFn: () => [] });
  const [initialized, setInitialized] = useState(false);
  const [warm, setWarm] = useState(false);
  useEffect(() => {
    async function init() {
      await prewarmMonth(month);
      setInitialized(true);
    }
    init();
    warmCategories(month).then(() => setWarm(true));
  }, [month]);
  return <p data-warm={warm}>{String(initialized)}</p>;
}
